const rows = name => $(name).all().map(i => i.json);
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const num = v => (v === null || v === undefined || v === '') ? null : Number(v);
const wat = iso => iso ? new Date(iso).toLocaleString('en-GB', { timeZone: 'Africa/Lagos', hour12: false }) : '-';
const mins = m => m === null ? '-' : (m >= 60 ? `${Math.floor(m / 60)}h ${m % 60}m` : `${m}m`);

const q1 = rows('Q1').filter(r => r.intent);
const escRate = num(rows('Q2')[0]?.pct);
const q3 = rows('Q3').filter(r => r.id !== undefined && r.id !== null);
const humanMin = num(rows('Q4')[0]?.human_first_response_min);
const botSec = num(rows('Q5')[0]?.bot_response_sec);
const q6 = rows('Q6').filter(r => r.event);
const breaches = num(rows('Q7')[0]?.breaches) ?? 0;

const total = q1.reduce((s, r) => s + Number(r.n), 0);
const maxN = Math.max(1, ...q1.map(r => Number(r.n)));
const botResolved = escRate === null ? null : +(100 - escRate).toFixed(1);

const failEvents = ['duplicate_ignored','low_confidence','notify_failed','send_failed',
                    'signature_invalid','malformed_payload','workflow_error'];
const failMap = Object.fromEntries(q6.map(r => [r.event, Number(r.n)]));

const card = (label, value, sub = '') =>
  `<div class="card"><div class="label">${esc(label)}</div><div class="value">${esc(value)}</div><div class="sub">${esc(sub)}</div></div>`;

const bars = q1.length
  ? q1.map(r => `<div class="barrow"><span class="bl">${esc(r.intent)}</span>
      <span class="bar"><span style="width:${Math.round(Number(r.n) / maxN * 100)}%"></span></span>
      <span class="bn">${esc(r.n)}</span></div>`).join('')
  : '<p class="muted">No messages in the last 7 days.</p>';

const caseRows = q3.length
  ? q3.map(r => {
      const late = r.status === 'open' && new Date(r.sla_due_at) < new Date();
      return `<tr class="${late ? 'late' : ''}"><td>#${esc(r.id)}</td><td>${esc(r.category)}</td>
        <td>${esc(r.assigned_to)}</td><td>${esc(r.status)}</td><td>${esc(r.notify_status)}</td>
        <td>${mins(Number(r.age_min))}</td><td>${wat(r.sla_due_at)}</td></tr>`;
    }).join('')
  : '<tr><td colspan="7" class="muted">No unresolved cases.</td></tr>';

const failRows = failEvents.map(e =>
  `<tr class="${failMap[e] ? 'late' : ''}"><td>${esc(e)}</td><td>${failMap[e] || 0}</td></tr>`).join('');

const html = `<!doctype html>
<html lang="en"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="refresh" content="60">
<title>Zuri Operations Dashboard</title>
<style>
:root { --bg:#f6f7f9; --card:#fff; --text:#1c1f24; --muted:#6b7280; --line:#e5e7eb; --accent:#2563eb; --bad:#fee2e2; }
@media (prefers-color-scheme: dark) { :root { --bg:#111418; --card:#1a1f26; --text:#e8eaed; --muted:#9aa3af; --line:#2a313b; --accent:#60a5fa; --bad:#4a1d1d; } }
body { margin:0; padding:16px; font-family:system-ui,Arial,sans-serif; background:var(--bg); color:var(--text); }
h1 { font-size:20px; margin:0 0 4px; } h2 { font-size:15px; margin:24px 0 8px; }
.muted { color:var(--muted); font-size:13px; }
.grid { display:grid; grid-template-columns:repeat(auto-fit,minmax(160px,1fr)); gap:12px; margin-top:12px; }
.card { background:var(--card); border:1px solid var(--line); border-radius:8px; padding:12px; }
.label { font-size:12px; color:var(--muted); } .value { font-size:24px; font-weight:600; margin-top:4px; } .sub { font-size:11px; color:var(--muted); }
.panel { background:var(--card); border:1px solid var(--line); border-radius:8px; padding:12px; overflow-x:auto; }
.barrow { display:flex; align-items:center; gap:8px; margin:6px 0; font-size:13px; }
.bl { width:140px; } .bn { width:40px; text-align:right; }
.bar { flex:1; background:var(--line); border-radius:4px; height:12px; } .bar span { display:block; height:12px; background:var(--accent); border-radius:4px; }
table { border-collapse:collapse; width:100%; font-size:13px; } th,td { text-align:left; padding:6px 8px; border-bottom:1px solid var(--line); white-space:nowrap; }
tr.late td { background:var(--bad); }
</style></head><body>
<h1>Zuri Home &amp; Style: Operations</h1>
<div class="muted">Last 7 days. Updated ${wat(new Date().toISOString())} WAT. Refreshes every 60 seconds.</div>
<div class="grid">
${card('Messages', total)}
${card('Handled by bot', botResolved === null ? 'n/a' : botResolved + '%', 'bot-resolved share')}
${card('Escalation rate', escRate === null ? 'n/a' : escRate + '%')}
${card('Unresolved cases', q3.length)}
${card('SLA breaches', breaches, 'open and overdue')}
${card('Bot response', botSec === null ? 'n/a' : botSec + 's', 'average')}
${card('Human first response', humanMin === null ? 'n/a' : humanMin + ' min', 'average')}
</div>
<h2>Volume by intent</h2><div class="panel">${bars}</div>
<h2>Unresolved cases</h2><div class="panel"><table>
<tr><th>Case</th><th>Category</th><th>Assigned</th><th>Status</th><th>Notified</th><th>Age</th><th>SLA due (WAT)</th></tr>${caseRows}</table></div>
<h2>Failures and fallbacks</h2><div class="panel"><table><tr><th>Event</th><th>Count</th></tr>${failRows}</table></div>
</body></html>`;

return [{ json: { html } }];

parameters.query:
SELECT ROUND(100.0 *
  (SELECT COUNT(*) FROM escalations WHERE created_at >= now() - interval '7 days')
  / NULLIF((SELECT COUNT(*) FROM messages WHERE received_at >= now() - interval '7 days'), 0), 1) AS pct;

SELECT ROUND(AVG(EXTRACT(EPOCH FROM (first_response_at - created_at)) / 60)::numeric, 1) AS human_first_response_min
FROM escalations
WHERE first_response_at IS NOT NULL AND created_at >= now() - interval '7 days';

SELECT ROUND(AVG(EXTRACT(EPOCH FROM (responded_at - received_at)))::numeric, 1) AS bot_response_sec
FROM messages
WHERE handled_by = 'bot' AND responded_at IS NOT NULL AND received_at >= now() - interval '7 days';
